//! Source-proved record bootstrap lowering. Generated bytecode is compiled by
//! the normal ASM backend; no MethodHandle interpreter or host execution.
use super::{
    classfile::{ClassFile, MethodHandle},
    types,
};
use crate::{
    bytecode::{ClassOrigin, GeneratedOrigin},
    files,
};
use anyhow::{Context, Result, ensure};
use serde::{Deserialize, Serialize};

pub const MARKER: &str = "$$BoomRecord$";
pub const METHOD: &str = "$apply";
pub const BOOTSTRAP_OWNER: &str = "java/lang/runtime/ObjectMethods";
const BOOTSTRAP: &str = "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/invoke/TypeDescriptor;Ljava/lang/Class;Ljava/lang/String;[Ljava/lang/invoke/MethodHandle;)Ljava/lang/Object;";

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Plan {
    pub abi: u32,
    pub site: u16,
    pub host: String,
    pub class_name: String,
    pub descriptor: String,
    pub simple_name: String,
    pub fields: Vec<MethodHandle>,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Binding {
    pub caller: ClassOrigin,
    pub plan: Plan,
    pub generated: ClassOrigin,
    pub bootstrap: ClassOrigin,
    pub bootstrap_code_sha256: String,
    pub original_object_methods_java_body_executed: bool,
}
impl Plan {
    pub fn parse(class: &ClassFile, index: u16) -> Result<Self> {
        let site = class.dynamic_site(index)?;
        ensure!(
            site.bootstrap.reference_kind == 6
                && !site.bootstrap.interface
                && site.bootstrap.owner == BOOTSTRAP_OWNER
                && site.bootstrap.name == "bootstrap"
                && site.bootstrap.descriptor == BOOTSTRAP,
            "Record bootstrap signature changed"
        );
        ensure!(
            site.name == "toString",
            "Record ObjectMethods {} lowering is not implemented",
            site.name
        );
        let descriptor = format!("(L{};)Ljava/lang/String;", class.name);
        ensure!(
            site.descriptor == descriptor,
            "Record toString call-site descriptor changed"
        );
        ensure!(
            class.access & 0x610 == 0x10 && class.super_name == "java/lang/Record",
            "Record lowering requires a final Record subclass"
        );
        let components = class
            .record_components
            .as_ref()
            .context("Missing original Record attribute")?;
        ensure!(
            components.len() <= 32 && site.arguments.len() == components.len() + 2,
            "Record component/getter count exceeds the supported contract"
        );
        ensure!(
            class.constant_class(site.arguments[0])? == class.name,
            "Record bootstrap class identity changed"
        );
        let names = class
            .string_literal(site.arguments[1])?
            .context("Record component names must be a String constant")?;
        let expected_names = components
            .iter()
            .map(|(n, _)| n.as_str())
            .collect::<Vec<_>>()
            .join(";");
        ensure!(
            names == expected_names.encode_utf16().collect::<Vec<_>>(),
            "Record bootstrap names differ from the Record attribute"
        );
        let mut fields = Vec::new();
        for ((name, descriptor), &constant) in components.iter().zip(&site.arguments[2..]) {
            let getter = class.method_handle(constant)?;
            ensure!(
                getter.reference_kind == 1
                    && !getter.interface
                    && getter.owner == class.name
                    && &getter.name == name
                    && &getter.descriptor == descriptor,
                "Record bootstrap getter differs from the declared component"
            );
            let field = class
                .field_info
                .iter()
                .find(|f| f.name == *name && f.descriptor == *descriptor)
                .context("Missing record component backing field")?;
            ensure!(
                field.access & 0x18 == 0x10,
                "Record component must have a final instance backing field"
            );
            fields.push(getter);
        }
        Ok(Self {
            abi: 1,
            site: index,
            host: class.name.clone(),
            class_name: format!("{}{MARKER}{index:04x}", class.name),
            descriptor,
            simple_name: class
                .inner_simple_name
                .clone()
                .unwrap_or_else(|| class.name.rsplit('/').next().unwrap().into()),
            fields,
        })
    }
    pub fn definition(&self, host: &ClassOrigin) -> Result<(Vec<u8>, ClassOrigin)> {
        ensure!(
            host.generated.is_none() && host.binary_name == self.host.replace('/', "."),
            "Record creator must be original bytecode"
        );
        let bytes = generate(self)?;
        let origin = ClassOrigin {
            loader: host.loader.clone(),
            binary_name: self.class_name.replace('/', "."),
            source_id: "boom:record-v1".into(),
            jar_entry: format!("{}.class", self.class_name),
            java_class_major: 65,
            sha256: files::digest_bytes(&bytes).sha256,
            generated: Some(Box::new(GeneratedOrigin {
                generator: "boom-record".into(),
                abi: 1,
                host_loader: host.loader.clone(),
                host_class: self.host.clone(),
                host_source_id: host.source_id.clone(),
                host_sha256: host.sha256.clone(),
                site: self.site,
            })),
        };
        Ok((bytes, origin))
    }
    pub fn binding(
        &self,
        registry: &mut types::Registry<'_>,
        caller: &ClassOrigin,
    ) -> Result<Binding> {
        let id = registry.class("bootstrap", BOOTSTRAP_OWNER)?;
        let types::Type::Class { origin, .. } = &registry.types[id] else {
            unreachable!()
        };
        ensure!(
            origin.source_id == "jdk:java.base" && origin.generated.is_none(),
            "Record bootstrap requires original java.base source"
        );
        let method = registry
            .definition(id)
            .unwrap()
            .method("bootstrap", Some(BOOTSTRAP))?;
        ensure!(
            method.access & 0x109 == 9,
            "Record bootstrap must be public static Java Code"
        );
        let code = method
            .code
            .as_ref()
            .context("Record bootstrap Java Code is absent")?;
        Ok(Binding {
            caller: caller.clone(),
            plan: self.clone(),
            generated: self.definition(caller)?.1,
            bootstrap: origin.as_ref().clone(),
            bootstrap_code_sha256: files::digest_bytes(&code.bytes).sha256,
            original_object_methods_java_body_executed: false,
        })
    }
}
pub(super) fn resolve(
    base: &dyn types::TypeProvider,
    loader: &str,
    name: &str,
) -> Result<Option<(Vec<u8>, ClassOrigin)>> {
    let Some((host, site)) = name.rsplit_once(MARKER) else {
        return Ok(None);
    };
    if base.name_in_use(name)? {
        return Ok(None);
    }
    ensure!(
        !host.contains(MARKER) && site.len() == 4,
        "Invalid generated record identity"
    );
    let site = u16::from_str_radix(site, 16)?;
    let (bytes, origin) = base.resolve(loader, host)?;
    ensure!(
        files::digest_bytes(&bytes).sha256 == origin.sha256
            && origin.binary_name == host.replace('/', "."),
        "Record host source identity changed"
    );
    let plan = Plan::parse(&ClassFile::parse(&bytes)?, site)?;
    Ok(Some(plan.definition(&origin)?))
}
pub(super) fn validate(class: &ClassFile, origin: &ClassOrigin) -> Result<()> {
    let proof = origin
        .generated
        .as_ref()
        .context("Missing generated record proof")?;
    ensure!(
        proof.generator == "boom-record"
            && proof.abi == 1
            && origin.source_id == "boom:record-v1"
            && origin.loader == proof.host_loader
            && class.name == format!("{}{MARKER}{:04x}", proof.host_class, proof.site)
            && class.super_name == "java/lang/Object"
            && class.access == 0x1031
            && class.field_info.is_empty()
            && class.methods.len() == 1
            && class.methods[0].name == METHOD
            && class.methods[0].access == 0x1009
            && class.methods[0].descriptor == format!("(L{};)Ljava/lang/String;", proof.host_class),
        "Invalid compiler-owned record definition"
    );
    Ok(())
}

#[derive(Default)]
struct Pool(Vec<Vec<u8>>);
impl Pool {
    fn push(&mut self, bytes: Vec<u8>) -> Result<u16> {
        ensure!(
            self.0.len() < 65534,
            "Record template constant pool overflow"
        );
        self.0.push(bytes);
        Ok(self.0.len() as u16)
    }
    fn utf(&mut self, value: &str) -> Result<u16> {
        let mut encoded = Vec::new();
        for c in value.encode_utf16() {
            if c > 0 && c < 0x80 {
                encoded.push(c as u8);
            } else if c < 0x800 {
                encoded.extend([0xc0 | (c >> 6) as u8, 0x80 | (c & 63) as u8]);
            } else {
                encoded.extend([
                    0xe0 | (c >> 12) as u8,
                    0x80 | ((c >> 6) & 63) as u8,
                    0x80 | (c & 63) as u8,
                ]);
            }
        }
        ensure!(encoded.len() < 65536, "Record template UTF8 overflow");
        let mut item = vec![1];
        item.extend((encoded.len() as u16).to_be_bytes());
        item.extend(encoded);
        self.push(item)
    }
    fn pair(&mut self, tag: u8, a: u16, b: u16) -> Result<u16> {
        let mut item = vec![tag];
        item.extend(a.to_be_bytes());
        item.extend(b.to_be_bytes());
        self.push(item)
    }
    fn one(&mut self, tag: u8, index: u16) -> Result<u16> {
        let mut item = vec![tag];
        item.extend(index.to_be_bytes());
        self.push(item)
    }
    fn class(&mut self, name: &str) -> Result<u16> {
        let i = self.utf(name)?;
        self.one(7, i)
    }
    fn string(&mut self, text: &str) -> Result<u16> {
        let i = self.utf(text)?;
        self.one(8, i)
    }
    fn member(&mut self, tag: u8, owner: &str, name: &str, desc: &str) -> Result<u16> {
        let owner = self.class(owner)?;
        let n = self.utf(name)?;
        let d = self.utf(desc)?;
        let nt = self.pair(12, n, d)?;
        self.pair(tag, owner, nt)
    }
}
fn reference(code: &mut Vec<u8>, op: u8, index: u16) {
    code.push(op);
    code.extend(index.to_be_bytes());
}
fn generate(plan: &Plan) -> Result<Vec<u8>> {
    let mut p = Pool::default();
    let this = p.class(&plan.class_name)?;
    let parent = p.class("java/lang/Object")?;
    let code_name = p.utf("Code")?;
    let method_name = p.utf(METHOD)?;
    let method_desc = p.utf(&plan.descriptor)?;
    let mut code = Vec::new();
    let mut bootstrap = None;
    if plan.fields.is_empty() {
        let value = p.string(&format!("{}[]", plan.simple_name))?;
        reference(&mut code, 0x13, value);
    } else {
        let mut descriptor = "(".to_owned();
        for field in &plan.fields {
            code.push(0x2a);
            reference(
                &mut code,
                0xb4,
                p.member(9, &field.owner, &field.name, &field.descriptor)?,
            );
            match field.descriptor.as_str() {
                "F" | "D" => {
                    let owner = if field.descriptor == "F" {
                        "java/lang/Float"
                    } else {
                        "java/lang/Double"
                    };
                    reference(
                        &mut code,
                        0xb8,
                        p.member(
                            10,
                            owner,
                            "toString",
                            &format!("({})Ljava/lang/String;", field.descriptor),
                        )?,
                    );
                    descriptor.push_str("Ljava/lang/String;");
                }
                "J" | "Z" | "C" => descriptor.push_str(&field.descriptor),
                "I" | "B" | "S" => descriptor.push('I'),
                "Ljava/lang/String;" => descriptor.push_str("Ljava/lang/String;"),
                "Ljava/lang/Thread;" => {
                    code.push(0x59);
                    let branch = code.len();
                    code.extend([0xc7, 0, 0]);
                    code.push(0x57);
                    reference(&mut code, 0x13, p.string("null")?);
                    let finish = code.len();
                    code.extend([0xa7, 0, 0]);
                    let target = code.len();
                    reference(
                        &mut code,
                        0xb6,
                        p.member(10, "java/lang/Thread", "toString", "()Ljava/lang/String;")?,
                    );
                    let end = code.len();
                    code[branch + 1..branch + 3]
                        .copy_from_slice(&((target - branch) as u16).to_be_bytes());
                    code[finish + 1..finish + 3]
                        .copy_from_slice(&((end - finish) as u16).to_be_bytes());
                    descriptor.push_str("Ljava/lang/String;");
                }
                _ => {
                    reference(
                        &mut code,
                        0xb8,
                        p.member(
                            10,
                            "java/lang/String",
                            "valueOf",
                            "(Ljava/lang/Object;)Ljava/lang/String;",
                        )?,
                    );
                    descriptor.push_str("Ljava/lang/String;");
                }
            }
        }
        descriptor.push_str(")Ljava/lang/String;");
        let mut recipe = format!("{}[", plan.simple_name);
        for (i, field) in plan.fields.iter().enumerate() {
            if i != 0 {
                recipe.push_str(", ");
            }
            recipe.push_str(&field.name);
            recipe.push_str("=\u{1}");
        }
        recipe.push(']');
        let recipe = p.string(&recipe)?;
        let target=p.member(10,"java/lang/invoke/StringConcatFactory","makeConcatWithConstants","(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/invoke/MethodType;Ljava/lang/String;[Ljava/lang/Object;)Ljava/lang/invoke/CallSite;")?;
        let mut handle = vec![15, 6];
        handle.extend(target.to_be_bytes());
        let handle = p.push(handle)?;
        let name = p.utf("makeConcatWithConstants")?;
        let desc = p.utf(&descriptor)?;
        let nt = p.pair(12, name, desc)?;
        let dynamic = p.pair(18, 0, nt)?;
        reference(&mut code, 0xba, dynamic);
        code.extend([0, 0]);
        bootstrap = Some((p.utf("BootstrapMethods")?, handle, recipe));
    }
    code.push(0xb0);
    let mut bytes = vec![0xca, 0xfe, 0xba, 0xbe, 0, 0, 0, 65];
    bytes.extend(((p.0.len() + 1) as u16).to_be_bytes());
    for item in p.0 {
        bytes.extend(item);
    }
    for value in [
        0x1031,
        this,
        parent,
        0,
        0,
        1,
        0x1009,
        method_name,
        method_desc,
        1,
        code_name,
    ] {
        bytes.extend(value.to_be_bytes());
    }
    bytes.extend(((code.len() + 12) as u32).to_be_bytes());
    bytes.extend(80u16.to_be_bytes());
    bytes.extend(1u16.to_be_bytes());
    bytes.extend((code.len() as u32).to_be_bytes());
    bytes.extend(code);
    bytes.extend([0, 0, 0, 0]);
    if let Some((attribute, handle, recipe)) = bootstrap {
        bytes.extend(1u16.to_be_bytes());
        bytes.extend(attribute.to_be_bytes());
        bytes.extend(8u32.to_be_bytes());
        for value in [1, handle, 1, recipe] {
            bytes.extend(value.to_be_bytes());
        }
    } else {
        bytes.extend([0, 0]);
    }
    Ok(bytes)
}
